import { injectable } from 'inversify';
import { gameNameOverrides, IActiveTournamentData, IHistoryResponse, ILeaderboardEntry, ILeaderboardResponse, IPrizeLeagueServerResponse, ITournament, ITournamentHistoryEntry, IUserData } from './types';
import axios from 'axios';
import { ref } from 'vue';
import { queryStringParams } from '../query-string';
import { userModel } from '../../models/user';
import { eventEmitter } from '../..';
import { environment } from '../environment';
import { enrichUserData, truncateUsername } from '../../views/prize-league/prize-league-utils';

@injectable()
export class PrizeLeagueManager {
    private get baseUrl(): string {
        let envPrefix = environment === 'live' ? '' : `${environment}-`;
        if (environment === 'debug') {
            envPrefix = 'dev-';
        }
        return `https://${envPrefix}tournaments.tombola.com`;
    }
    public tournamentList = ref<Array<ITournament>>([]);
    public activeTournament = ref<IActiveTournamentData | null>(null);
    public currentlyViewedTournament = ref<ITournament | null>(null);
    public leaderboard = ref<ILeaderboardEntry[]>([]);
    public userData = ref<IUserData | null>(null);
    public isJoining = ref<boolean>(false);
    public joinResult = ref<'success' | 'error' | null>(null);
    public tournamentHistory = ref<Array<ITournamentHistoryEntry>>([]);
    public isCalculatingResults = ref<boolean>(false);
    public pendingResultsTournamentId = ref<string | null>(null);
    public tournamentResult = ref<ITournamentHistoryEntry | null>(null);

    // Pre-computed result display state — set by the manager so overlays don't need any logic
    public resultPrizeText = ref<string>('');
    public resultDidNotSpin = ref<boolean>(false);
    public resultShouldShowConfetti = ref<boolean>(false);

    private resultsPollInterval: ReturnType<typeof setInterval> | null = null;
    private calculatingStartTime: number | null = null;
    private tournamentStartTimeout: ReturnType<typeof setTimeout> | null = null;
    private static readonly MIN_CALCULATING_MS = 3000;
    private static readonly MAX_POLLING_MS = 60000;
    private leaderboardRefreshInterval: ReturnType<typeof setInterval> | null = null;
    private static readonly LEADERBOARD_REFRESH_MS = 10000;

    public async init() {
        this.tournamentList.value = [];

        eventEmitter.on('GAME_BEGIN', () => {
            this.stopLeaderboardAutoRefresh();
        });
        
        eventEmitter.on('GAME_COMPLETE', () => {
            const active = this.activeTournament.value;
            if (!active) return;

            // Don't update while calculating/showing results from the previous tournament
            if (this.isCalculatingResults.value || this.tournamentResult.value) return;

            this.fetchLeaderboard(active.tournamentId);
            this.restartLeaderboardAutoRefresh();
        });

        await this.checkForActiveTournament();
    }

    public async fetchTournaments() {
        const gameName = gameNameOverrides[queryStringParams.currentSkin] ?? queryStringParams.currentSkin;
        const userId = userModel.userId;
        const url = `${this.baseUrl}/tournaments?gamename=${gameName}&userid=${userId}`;
        const response: IPrizeLeagueServerResponse | undefined = await axios.get(url).then((response) => response.data).catch(() => undefined);

        if (!response) {
            return;
        }
        this.tournamentList.value = response.tournaments.map((tournament) => ({
            ...tournament,
            startTimeObject: new Date(tournament.startTime)
        }));
    }

    public async fetchLeaderboard(tournamentId: string) {
        const userId = userModel.userId;
        const url = `${this.baseUrl}/leaderboard?tournamentid=${tournamentId}&userid=${userId}`;
        const response: ILeaderboardResponse | undefined = await axios.get(url).then((response) => response.data).catch(() => undefined);

        this.leaderboard.value = [];
        if (response) {
            response.leaderboard.forEach(e => e.username = truncateUsername(e.username));
            this.leaderboard.value = response.leaderboard;
            this.userData.value = enrichUserData(response.user);
            this.updateActiveTournamentData(tournamentId, response);
        } else {
            this.updateActiveTournamentData(tournamentId);
        }

        // Reset the auto-refresh timer whenever leaderboard is fetched
        this.restartLeaderboardAutoRefresh();
    }

    public async optInToTournament(tournamentId: string): Promise<boolean> {
        this.isJoining.value = true;
        this.joinResult.value = null;
        
        const userId = userModel.userId;
        const crossCheck = userModel.crossCheck;
        const url = `${this.baseUrl}/optin`;
        const response = await axios.post(url, { 'tournamentId': tournamentId, 'userId': userId, 'cc': crossCheck }).then((response) => response.data).catch(() => undefined);

        this.isJoining.value = false;

        if (response) {
            this.joinResult.value = 'success';
            await this.fetchTournaments();
            
            const tournament = this.tournamentList.value.find(t => t.tournamentId === tournamentId);
            if (tournament) {
                // Update the currently viewed tournament reference so Vue reactivity
                // picks up the new hasOptedIn value immediately
                this.currentlyViewedTournament.value = tournament;

                if (tournament.tournamentStatus === 'Active') {
                    await this.fetchLeaderboard(tournamentId);
                    this.scheduleActiveTournamentEnd();
                } else if (tournament.tournamentStatus === 'Upcoming') {
                    this.scheduleTournamentStart(tournament.secondsToStart);
                }
            }
        } else {
            this.joinResult.value = 'error';
        }

        // Auto-hide the result message after 3 seconds
        setTimeout(() => {
            this.joinResult.value = null;
        }, 3000);

        return this.joinResult.value === 'success';
    }

    public updateActiveTournamentData(tournamentId: string, leaderboardData?: ILeaderboardResponse) {
        const tournament = this.tournamentList.value.find(t => t.tournamentId === tournamentId);

        // If the tournament is no longer active but we have fresh leaderboard data for it,
        // patch totalPlayers on the existing activeTournament so the header stays up to date.
        if (!tournament || tournament.tournamentStatus !== 'Active') {
            if (leaderboardData && this.activeTournament.value?.tournamentId === tournamentId) {
                this.activeTournament.value = {
                    ...this.activeTournament.value,
                    totalPlayers: leaderboardData.totalPlayers
                };
            }
            return;
        }

        this.activeTournament.value = {
            tournamentId: tournamentId,
            totalSpins: tournament.noOfSpins,
            spinsUsed: tournament.noOfSpins - (leaderboardData?.user.spinsRemaining ?? tournament.noOfSpins),
            totalPlayers: leaderboardData?.totalPlayers ?? 0,
            secondsToEnd: tournament.secondsToEnd,
            isOptedIn: tournament.hasOptedIn
        };
    }

    public async checkForActiveTournament() {
        this.activeTournament.value = null;
        await this.fetchTournaments();

        if (this.tournamentList.value) {
            const firstTournament = this.tournamentList.value[0];
            if (firstTournament?.tournamentStatus === 'Active') {
                await this.fetchLeaderboard(firstTournament.tournamentId);
                if (this.currentlyViewedTournament.value?.tournamentId === firstTournament.tournamentId) {
                    //Update currently viewed tournament data
                    this.setCurrentlyViewedTournament(firstTournament.tournamentId);
                }
                this.scheduleActiveTournamentEnd();
            } 
            //scan through list for an opted in tournament
            const optedIn = this.tournamentList.value.filter(t => t.tournamentStatus === 'Upcoming').find(t => t.hasOptedIn);
            if (optedIn) {
                this.scheduleTournamentStart(optedIn.secondsToStart);
            }
        }

        await this.fetchTournamentHistory();
    }

    public async onReturnToTournamentList() {
        const viewed = this.currentlyViewedTournament.value;
        const active = this.activeTournament.value;

        const viewedConcluded = viewed && this.isTournamentConcluded(viewed);
        const activeConcluded = active && active.secondsToEnd <= 0;

        if (viewedConcluded || activeConcluded) {
            this.activeTournament.value = null;
            await this.fetchTournaments();

            const firstTournament = this.tournamentList.value[0];
            if (firstTournament?.tournamentStatus === 'Active') {
                await this.fetchLeaderboard(firstTournament.tournamentId);
            }
        }
    }

    public setCurrentlyViewedTournament(tournamentId: string) {
        const tournament = this.tournamentList.value.find(t => t.tournamentId === tournamentId);
        if (tournament) {
            // Clear stale leaderboard data when switching tournaments
            const previousId = this.currentlyViewedTournament.value?.tournamentId;
            if (previousId && previousId !== tournamentId) {
                this.leaderboard.value = [];
                this.userData.value = null;
            }

            this.currentlyViewedTournament.value = tournament;
        }
    }

    public clearCurrentlyViewedTournament() {
        this.currentlyViewedTournament.value = null;
    }

    private activeTournamentEndTimeout: ReturnType<typeof setTimeout> | null = null;

    /**
     * Schedules the end-of-tournament results flow based on the active tournament.
     * Runs regardless of what panel the player is viewing.
     * When it fires, it navigates them to the leaderboard and starts polling.
     */
    private scheduleActiveTournamentEnd() {
        this.clearActiveTournamentEnd();

        const active = this.activeTournament.value;
        if (!active || !active.isOptedIn) return;
        if (active.secondsToEnd <= 0) return;

        this.activeTournamentEndTimeout = setTimeout(() => {
            this.startCalculatingResults(active.tournamentId);
        }, (active.secondsToEnd + 1) * 1000);
    }

    private clearActiveTournamentEnd() {
        if (this.activeTournamentEndTimeout) {
            clearTimeout(this.activeTournamentEndTimeout);
            this.activeTournamentEndTimeout = null;
        }
    }

    public startCalculatingResults(tournamentId: string) {
        this.stopLeaderboardAutoRefresh();
        this.pendingResultsTournamentId.value = tournamentId;
        this.isCalculatingResults.value = true;
        this.tournamentResult.value = null;
        this.calculatingStartTime = Date.now();

        this.pollForResults();
    }

    private pollForResults() {
        this.stopPollingResults();

        // Poll immediately, then every 5 seconds
        this.checkForResults();
        this.resultsPollInterval = setInterval(() => {
            this.checkForResults();
        }, 5000);
    }

    private async checkForResults() {
        const tournamentId = this.pendingResultsTournamentId.value;
        if (!tournamentId) {
            return;
        }

        // Give up after 60 seconds of polling
        const elapsed = Date.now() - (this.calculatingStartTime ?? 0);
        if (elapsed >= PrizeLeagueManager.MAX_POLLING_MS) {
            this.clearResultsState();
            return;
        }

        await this.fetchTournamentHistory();

        const entry = this.tournamentHistory.value.find(
            t => t.tournamentId === tournamentId
        );

        if (!entry) {
            return;
        }

        const elapsedSinceStart = Date.now() - (this.calculatingStartTime ?? 0);
        const remaining = PrizeLeagueManager.MIN_CALCULATING_MS - elapsedSinceStart;

        const applyResults = () => {
            this.tournamentResult.value = entry;
            this.leaderboard.value = entry.leaderboard;
            this.isCalculatingResults.value = false;
            this.stopPollingResults();
            this.computeResultDisplayState(entry);
            eventEmitter.emit('SHOW_PRIZE_LEAGUE_RESULTS');
        };

        if (remaining > 0) {
            setTimeout(applyResults, remaining);
        } else {
            applyResults();
        }
    }

    private stopPollingResults() {
        if (this.resultsPollInterval) {
            clearInterval(this.resultsPollInterval);
            this.resultsPollInterval = null;
        }
    }

    public clearResultsState() {
        this.stopPollingResults();
        this.stopLeaderboardAutoRefresh();
        this.clearActiveTournamentEnd();
        this.pendingResultsTournamentId.value = null;
        this.tournamentResult.value = null;
        this.isCalculatingResults.value = false;
        this.leaderboard.value = [];
        this.userData.value = null;
        this.resultPrizeText.value = '';
        this.resultDidNotSpin.value = false;
        this.resultShouldShowConfetti.value = false;
    }

    public async fetchTournamentHistory() {
        const gameName = gameNameOverrides[queryStringParams.currentSkin] ?? queryStringParams.currentSkin;
        const userId = userModel.userId;
        const url = `${this.baseUrl}/history?gamename=${gameName}&userid=${userId}`;
        const response: IHistoryResponse | undefined = await axios.get(url).then((response) => response.data).catch(() => undefined);

        if (response) {
            response.tournaments.forEach(t => enrichUserData(t.user));
            this.tournamentHistory.value = response.tournaments;
        }
    }

    public isTournamentConcluded(tournament: ITournament): boolean {
        return tournament.tournamentStatus === 'Completed' || new Date() > new Date(tournament.endTime);
    }

    /**
     * Starts or restarts the auto-refresh timer for leaderboard updates.
     * Only runs if there's an active tournament and the player is opted in.
     */
    private restartLeaderboardAutoRefresh() {
        this.stopLeaderboardAutoRefresh();

        const active = this.activeTournament.value;
        if (!active || !active.isOptedIn) {
            return;
        }

        this.leaderboardRefreshInterval = setInterval(() => {
            const currentActive = this.activeTournament.value;
            if (!currentActive || !currentActive.isOptedIn) {
                this.stopLeaderboardAutoRefresh();
                return;
            }
            
            this.fetchLeaderboard(currentActive.tournamentId);
        }, PrizeLeagueManager.LEADERBOARD_REFRESH_MS);
    }

    /**
     * Computes and stores the result display state so overlays can render
     * without containing any business logic.
     */
    private computeResultDisplayState(entry: ITournamentHistoryEntry): void {
        const didNotSpin = !entry.user.found || (entry.user.score === 0 && entry.user.spinsRemaining === entry.noOfSpins);
        const prize = didNotSpin ? undefined : entry.prizes.find(p => p.position === entry.user.position);
        const prizeText = prize ? prize.displayText : '';

        this.resultDidNotSpin.value = didNotSpin;
        this.resultPrizeText.value = prizeText;
        this.resultShouldShowConfetti.value = !didNotSpin && !!prizeText;
    }

    /**
     * Stops the auto-refresh timer for leaderboard updates.
     */
    private stopLeaderboardAutoRefresh() {
        if (this.leaderboardRefreshInterval) {
            clearInterval(this.leaderboardRefreshInterval);
            this.leaderboardRefreshInterval = null;
        }
    }

    private scheduleTournamentStart(secondsToStart: number) {
        if (this.tournamentStartTimeout) {
            clearTimeout(this.tournamentStartTimeout);
        }
        this.tournamentStartTimeout = setTimeout(() => {
            this.tournamentStartTimeout = null;
            this.checkForActiveTournament();
        }, (secondsToStart + 1) * 1000);
            
    }
}